def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(min(budget, max(0.0, base)))

    pressure_bids = []
    aggressive_count = 0
    moderate_count = 0
    needy_count = 0

    for opp in alive_opps:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            needy_count += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            pressure_bids.append(float(bid))
            if bid >= 120:
                aggressive_count += 1
            elif bid >= 50:
                moderate_count += 1

    highest_prev = max(pressure_bids) if pressure_bids else 0.0
    active_prev = [b for b in pressure_bids if b > 0]
    avg_prev = sum(active_prev) / len(active_prev) if active_prev else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    risk = 0
    if hp <= 2:
        risk += 3
    elif hp <= 4:
        risk += 2
    elif hp <= 6:
        risk += 1
    if no_water_days >= 2:
        risk += 3
    elif no_water_days >= 1:
        risk += 2

    if day >= 8:
        risk += 1

    base = DAILY_SALARY * 0.38

    if scarcity == 2:
        base = DAILY_SALARY * 0.72
    elif scarcity == 1:
        base = DAILY_SALARY * 0.55

    if highest_prev >= 180:
        if risk >= 3:
            base = max(base, DAILY_SALARY * 0.82)
        else:
            base = min(base, DAILY_SALARY * 0.34)
    elif highest_prev >= 100:
        if risk >= 2:
            base = max(base, min(DAILY_SALARY * 0.78, avg_prev + 6.0))
        else:
            base = max(base, DAILY_SALARY * 0.46)
    elif highest_prev > 0:
        base = max(base, min(DAILY_SALARY * 0.74, highest_prev + 4.0))

    if aggressive_count >= 1 and risk <= 1 and scarcity == 0:
        base = min(base, DAILY_SALARY * 0.32)

    if moderate_count >= 1 and scarcity >= 1:
        base = max(base, avg_prev + 3.0)

    if needy_count >= 2 and risk >= 2:
        base = max(base, DAILY_SALARY * 0.8)

    reserve_target = 0.0
    days_left = 10 - day
    if days_left > 0:
        reserve_target = days_left * DAILY_SALARY * 0.18

    affordable = budget - reserve_target
    if affordable < 0:
        affordable = budget * 0.5

    bid = min(base, budget, affordable if affordable > 0 else budget)

    if risk >= 4:
        bid = max(bid, min(budget, DAILY_SALARY * 0.92))
    elif risk >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.7))

    if supply >= 23 and risk == 0:
        bid = min(bid, DAILY_SALARY * 0.28)

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, bid conservatively
    if not alive_opps:
        return max(0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))

    # Estimate how tight the day is; higher supply reduces need to overbid
    # (use ratio but keep simple)
    supply_ratio = 0.0
    if MAX_SUPPLY > 0:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    # clamp
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Detect Cindy aggression/budget crash from her yesterday trace
    cindy = opponents_status.get('Cindy', None)
    cindy_aggressive = False
    cindy_budget_crashed = False
    if cindy is not None:
        prev = cindy.get('previous_trace', {}) or {}
        c_bid = prev.get('bid', None)
        if c_bid is not None:
            try:
                if float(c_bid) >= DAILY_SALARY * 1.5:
                    cindy_aggressive = True
            except Exception:
                pass
        # if she ended yesterday with 0 budget, likely budget-constrained
        try:
            if float(cindy.get('budget', 0)) <= 0.0:
                cindy_budget_crashed = True
        except Exception:
            pass

    # Determine a target bid band
    # Base: moderate bid to stay competitive
    # If our hp is low, raise urgency.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    elif my_hp <= 7:
        urgency = 0.4
    else:
        urgency = 0.25

    # If Cindy was aggressive and budget-crashed, we can undercut slightly but still pressure.
    # If overall yesterday bids were high, increase slightly.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    base_bid = DAILY_SALARY * (0.45 + 0.25 * (1.0 - supply_ratio))  # tighter supply -> higher

    # Pressure adjustment
    if cindy_aggressive and cindy_budget_crashed:
        # Cindy likely cannot sustain aggression; bid just enough to beat her if she still tries.
        target = base_bid * (1.05 + 0.15 * urgency)
    else:
        # If yesterday market was hot, follow partially
        if highest_prev_bid >= DAILY_SALARY * 1.8:
            target = base_bid * (1.15 + 0.25 * urgency)
        elif avg_prev_bid >= DAILY_SALARY * 1.1:
            target = base_bid * (1.05 + 0.2 * urgency)
        else:
            target = base_bid * (0.95 + 0.2 * urgency)

    # Ensure we can afford it; also avoid overbidding beyond reasonable fraction of budget
    # (budget is finite; also prevent bidding too low when hp is critical)
    max_reasonable = my_budget
    if my_hp <= 2:
        max_reasonable = my_budget  # can spend to survive
    else:
        # keep some buffer
        max_reasonable = min(my_budget, DAILY_SALARY * 1.2)

    # Final clamp
    bid = float(target)
    if bid < 0:
        bid = 0.0
    if bid > max_reasonable:
        bid = max_reasonable

    # If our hp is extremely low, bid more aggressively
    if my_hp <= 1:
        bid = min(my_budget, DAILY_SALARY * 0.95)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50

    if my_status['hp'] < 4:
        bid = avg_prev_bid * 1.2
    else:
        bid = avg_prev_bid * 0.95

    return int(min(my_status['budget'], max(bid, 40)))
